∀ {V : Type u} [inst : CategoryTheory.Category.{v, u} V] {F : KomorebiSpace.ViewSystem V}
  {G : KomorebiSpace.ViewSystem V} {H : KomorebiSpace.ViewSystem V} (f : F.Morphism G) (g : G.Morphism H)
  (x : F.Ambient), (f.comp g).onAmbient x = g.onAmbient (f.onAmbient x)

∀ {𝕜 : Type u} [inst : NontriviallyNormedField 𝕜] (X : KomorebiSpace.BanachTower 𝕜) {Y : KomorebiSpace.BanachTower 𝕜}
  (L : Y.Splitting) (hgap : ↑L.bound * ↑X.bound < 1) (r : ↥(X.Residuals Y)),
  (X.differential Y) ((KomorebiSpace.BanachTower.Splitting.correction X L hgap) r) = r

∀ {V : Type u} [inst : CategoryTheory.Category.{v, u} V] {G : V → Type w} [inst_1 : (a : V) → Group (G a)] {I : Type z}
  {F : KomorebiSpace.GroupViewSystem V G} {U : I → Set V} {D : F.CocycleDescentData U} (E E' : D.Effectuation),
  KomorebiSpace.ViewSystem.TransitionCover U → ∃! a, E.Compatible E' a

∀ {V : Type u} {H : Type v} [inst : NormedAddCommGroup H] [inst_1 : NormedSpace ℝ H]
  (T : KomorebiSpace.AmplifiedTransport.Connection V H) {graph : SimpleGraph V} (x : V → H) {i j : V}
  (p : graph.Walk i j), T.walkSum (fun a => T.defect x (↑a).1 (↑a).2) p = (T.walkTransport p) (x j) - x i

∀ {E : Type u} {R : Type v} [inst : NormedAddCommGroup E] [inst_1 : InnerProductSpace ℝ E]
  [inst_2 : NormedAddCommGroup R] [inst_3 : NormedSpace ℝ R] [inst_4 : CompleteSpace R] {d e : E →L[ℝ] R}
  (T : KomorebiSpace.SplitKernel.Certificate d e) (r : R), e (T.perturbedSection r) = r
